"use client";

import { useState, useEffect } from "react";
import Header from "@/components/common/Header";
import Navbar from "@/components/common/Navbar";
import Footer from "@/components/common/Footer";
import Sidebar from "@/components/common/AdminSidebar";
import axios from "axios";


type Admin = {
  id: number;
  email: string;
  role: "Warehouse_Admin" | "Super_Admin";
  fullname: string;
};

const AdminManagement = () => {
  const [admins, setAdmins] = useState<Admin[]>([]);
  const [newAdmin, setNewAdmin] = useState<Admin>({
    id: 0,
    email: "",
    role: "Warehouse_Admin",
    fullname: "",
  });
  const [editingAdmin, setEditingAdmin] = useState<Admin | null>(null);

  useEffect(() => {
    const fetchAdmins = async () => {
      try {
        const response = await axios.get(`${process.env.NEXT_PUBLIC_BACKEND_URL}/api/v1/admin`);
        setAdmins(response.data);
      } catch (error) {
        console.error("Error fetching admins:", error);
      }
    };

    fetchAdmins();
  }, []);

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
    const { name, value } = e.target;
    setNewAdmin((prev) => ({
      ...prev,
      [name]: value,
    }));
  };

  const handleAdminSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      if (editingAdmin) {
        await axios.put(
          `${process.env.NEXT_PUBLIC_BACKEND_URL}/api/v1/admin/${editingAdmin.id}`,
          newAdmin
        );
      } else {
        await axios.post(`${process.env.NEXT_PUBLIC_BACKEND_URL}/api/v1/admin`, newAdmin);
      }
      setNewAdmin({ id: 0, email: "", fullname: "", role: "Warehouse_Admin" });
      setEditingAdmin(null);
      const response = await axios.get(`${process.env.NEXT_PUBLIC_BACKEND_URL}/api/v1/admin`);
      setAdmins(response.data);
    } catch (error) {
      console.error("Error creating or updating admin:", error);
    }
  };

  const handleEdit = (admin: Admin) => {
    setEditingAdmin(admin);
    setNewAdmin({
      id: admin.id,
      email: admin.email,
      role: admin.role,
      fullname: admin.fullname,
    });
  };

  const handleDelete = async (adminId: number) => {
    try {
      await axios.delete(`${process.env.NEXT_PUBLIC_BACKEND_URL}/api/v1/admin/${adminId}`);
      const response = await axios.get(`${process.env.NEXT_PUBLIC_BACKEND_URL}/api/v1/admin`);
      setAdmins(response.data);
    } catch (error) {
      console.error("Error deleting admin:", error);
    }
  };

  return (
    <div className="flex min-h-screen flex-col bg-gray-100 text-black">
      <Header />
      <Navbar />
      <div className="flex flex-grow">
        <Sidebar />
        <main className="flex-grow p-6 bg-white shadow-md">
          <h1 className="text-xl font-bold mb-4">Admin Management</h1>
          <div className="p-4 bg-gray-200 shadow rounded-lg mb-6">
            <h2 className="text-lg font-bold mb-4">{editingAdmin ? "Edit Admin" : "Create New Admin"}</h2>
            <form onSubmit={handleAdminSubmit}>
              <input
                type="text"
                name="fullname"
                value={newAdmin.fullname}
                onChange={handleInputChange}
                placeholder="Full Name"
                className="w-full p-2 mb-2 border rounded-lg"
                required
              />
              <input
                type="email"
                name="email"
                value={newAdmin.email}
                onChange={handleInputChange}
                placeholder="Email"
                className="w-full p-2 mb-2 border rounded-lg"
                required
              />
              <select
                name="role"
                value={newAdmin.role}
                onChange={handleInputChange}
                className="w-full p-2 mb-4 border rounded-lg"
              >
                <option value="Warehouse_Admin">Warehouse Admin</option>
                <option value="Super_Admin">Super Admin</option>
              </select>
              <button
                type="submit"
                className="px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-500"
              >
                {editingAdmin ? "Update Admin" : "Create Admin"}
              </button>
            </form>
          </div>

          <h2 className="text-xl font-bold mb-4">Admin Users</h2>
          <table className="w-full border border-gray-300">
            <thead>
              <tr className="bg-gray-200">
                <th className="border p-2">Username</th>
                <th className="border p-2">Email</th>
                <th className="border p-2">Role</th>
                <th className="border p-2">Actions</th>
              </tr>
            </thead>
            <tbody>
              {admins.map((admin) => (
                <tr key={admin.id}>
                  <td className="border p-2">{admin.fullname}</td>
                  <td className="border p-2">{admin.email}</td>
                  <td className="border p-2">{admin.role}</td>
                  <td className="border p-2">
                    <button
                      className="bg-yellow-500 text-white px-3 py-1 rounded mr-2"
                      onClick={() => handleEdit(admin)}
                    >
                      Edit
                    </button>
                    <button
                      className="bg-red-500 text-white px-3 py-1 rounded"
                      onClick={() => handleDelete(admin.id)}
                    >
                      Delete
                    </button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </main>
      </div>
      <Footer />
    </div>
  );
};

export default AdminManagement;
